// meshNoticeClass maps one notice tone onto the existing alert classes.
func meshNoticeClass(class string) string {
	if class == "error" {
		return "error"
	}
	return "notice"
}

// meshStatusDotClass maps the row status badge onto an independent dot tone.
// It never reuses badge classes: .badge brings padding and min-height that
// would stretch the 10px dot into an ellipse.
func meshStatusDotClass(statusClass string) string {
	switch statusClass {
	case "badge accent":
		return "status-dot ok"
	case "badge failure":
		return "status-dot fail"
	default:
		return "status-dot"
	}
}

// meshRouteSummary compacts one device's subnet declarations for the row bar.
// It names only the declared prefixes already listed in the route table below.
func meshRouteSummary(routes []MeshRouteView) string {
	if len(routes) == 0 {
		return "—"
	}
	if len(routes) == 1 {
		return routes[0].Prefix
	}
	return routes[0].Prefix + " 等 " + strconv.Itoa(len(routes)) + " 个前缀"
}

// meshObservedLabel renders the last persisted observation honestly: an empty
// value means the device was never reconciled, not that it is offline.
func meshObservedLabel(observed string) string {
	if observed == "" {
		return "尚未核对 · 从未观测"
	}
	return observed
}

